const int kFFXILoreZoneDatCount = (int)(sizeof(kFFXILoreZoneDatTable) / sizeof(kFFXILoreZoneDatTable[0]));

const FFXILoreZoneDatEntry* FFXILoreZoneDat_FindByZoneID(const int zoneId)
{
    for (int i = 0; i < kFFXILoreZoneDatCount; ++i)
    {
        if (kFFXILoreZoneDatTable[i].daturaZoneId == zoneId) return &kFFXILoreZoneDatTable[i];
    }
    return nullptr;
}

const FFXILoreZoneDatEntry* FFXILoreZoneDat_FindByWikiName(const char* wikiName)
{
    if (!wikiName || !wikiName[0]) return nullptr;
    for (int i = 0; i < kFFXILoreZoneDatCount; ++i)
    {
        if (std::strcmp(kFFXILoreZoneDatTable[i].ffxiclopediaZoneName, wikiName) == 0) return &kFFXILoreZoneDatTable[i];
    }
    return nullptr;
}
